import importlib.util
import sys
from pathlib import Path
from typing import Any, Callable

class PluginLoader:
    """Dynamically load and execute transformation plugins"""

    def __init__(self, plugin_dir: str = 'plugins'):
        self.plugin_dir = Path(plugin_dir)
        self._loaded_plugins = {}

    def load_plugin(self, plugin_name: str) -> Any:
        """Load a plugin module by name"""
        plugin_path = self.plugin_dir / f'{plugin_name}.py'

        if not plugin_path.exists():
            raise FileNotFoundError(f'Plugin not found: {plugin_path}')

        spec = importlib.util.spec_from_file_location(plugin_name, plugin_path)
        module = importlib.util.module_from_spec(spec)
        sys.modules[plugin_name] = module
        spec.loader.exec_module(module)

        self._loaded_plugins[plugin_name] = module
        return module

    def run_transform(self, plugin_name: str, data: Any) -> Any:
        """Execute the transform function from a loaded plugin"""
        if plugin_name not in self._loaded_plugins:
            self.load_plugin(plugin_name)

        module = self._loaded_plugins[plugin_name]
        if not hasattr(module, 'transform'):
            raise AttributeError(f'Plugin {plugin_name} missing transform function')

        return module.transform(data)

