def collect_targets(root: Path) -> list[Path]:
    targets = []
    for entry in root.rglob('*'):
        if entry.is_file() or entry.is_dir():
            targets.append(entry)
    return sorted(targets, key=lambda p: len(p.parts), reverse=True)
